```js
// in externalapi.js
const instance = axios.create({
    baseUrl: 'https://something.com',
    headers: {
        'X-Api-Key': 'secretstring',
    }
});

// in useapi.js
instance.get('/somethnig'); // oops, typo; throws 404 error
```

