_Actual Behavior_: Memory use slowly grows over time

```
//File: main.js
const axios = require('axios')

// localhost:3001/bad
const client = axios.create({
  baseURL: 'http://localhost:3001'
})

const work = async () => {
  try {
    await client.get('/bad')
    console.log('did it')
  } catch (error) {
    console.log('an error')
  }
}

const main = () => {
  setInterval(work, 0)
}
main()
