    }

    const body = JSON.stringify({ refreshToken });

    const { data } = await luggleApi.post<RefreshResponse>(
      "/accounts/refresh",
      {
        body,
        signal,
      },
    );

    if (isError(data)) {
      return {
        ok: false,
        error: {
          title: data.code,
          message: data.description,
        },
      };
    }

    const { accessToken, refreshToken: newRefreshToken, ...user } = data;

    return {
      ok: true,
      data: { user: user, token: { value: accessToken, refreshToken } },
    };
  } catch (error) {
    if (!isAxiosError(error)) {
      console.error(error);
      return {
        ok: false,
        error: {
          title: "Unexpected Error",
          message: "An unexpected error occurred. Please try again later.",
        },
      };
